import React from "react";

const Pagination = ({ filter, setFilter, totalCount }) => {
    if (!setFilter || typeof setFilter !== "function") {
        console.error("setFilter is not a function!");
        return null; // Nezobrazuj stránkování, pokud není správná funkce
    }

    const totalPages = Math.max(1, Math.ceil(totalCount / filter.limit));

    if (totalPages === 1) return null; // Skryje stránkování, pokud není potřeba

    const handlePageChange = (newPage) => {
        if (newPage < 0 || newPage >= totalPages) return; // Zabrání neplatným hodnotám
        setFilter((prev) => ({ ...prev, page: newPage }));
    };

    return (
        <nav>
            <ul className="pagination justify-content-center mt-3">
                <li className={`page-item ${filter.page === 0 ? "disabled" : ""}`}>
                    <button
                        className="page-link"
                        onClick={() => handlePageChange(filter.page - 1)}
                        disabled={filter.page === 0}
                    >
                        Předchozí
                    </button>
                </li>

                {Array.from({ length: totalPages }, (_, index) => (
                    <li key={index} className={`page-item ${filter.page === index ? "active" : ""}`}>
                        <button className="page-link" onClick={() => handlePageChange(index)}>
                            {index + 1}
                        </button>
                    </li>
                ))}

                <li className={`page-item ${filter.page >= totalPages - 1 ? "disabled" : ""}`}>
                    <button
                        className="page-link"
                        onClick={() => handlePageChange(filter.page + 1)}
                        disabled={filter.page >= totalPages - 1}
                    >
                        Další
                    </button>
                </li>
            </ul>
        </nav>
    );
};

export default Pagination;
